import type { Continent, Destination, SpotCategory } from '../types';
import { DESTINATIONS } from './destinations';
import { PARK_PASSES, type ParkPassId } from './parkPasses';

export interface Spot {
  id: string;
  // The destination this spot belongs to — OMITTED for a STANDALONE spot: one with no appropriate destination to
  // sit under, or too few neighbouring spots to make one (see COVERAGE.md). A standalone spot instead carries
  // the place context a destination would have supplied (country, countryCode, continent, timezone), all required
  // when destinationId is absent. Read these through spotCountryCode / spotCountry / spotTimezone / spotDestination,
  // never through destinationId directly.
  destinationId?: string;
  country?: string;
  countryCode?: string;
  continent?: Continent;
  timezone?: string;       // IANA, e.g. "Pacific/Auckland"
  // The name shown in the app: the place's own name, title-cased, with no destination or country tacked on
  // ("Russell", not "Russell, New Zealand"). The app looks the spot's photo up by `wiki` when given, else by `name`.
  name: string;
  // Exact Wikipedia article title, when it differs from `name` — usually a disambiguated title such as
  // "Russell, New Zealand". Photo lookups, image overrides and the manifest key on this. See spotPhotoTitle.
  wiki?: string;
  icon: string;
  coordinates: { latitude: number; longitude: number };
  category: SpotCategory;
  bio: string;
  // Approximate time to visit, always a range (not a single estimate — visit length varies
  // too much person to person for one number to read as anything but false precision).
  visitHoursMin: number;
  visitHoursMax: number;
  // Entry cost in the spot's own local currency (approximate — sourced from general
  // knowledge, not a live pricing feed, so treat as a starting point rather than gospel;
  // venues change prices often). `free: true` takes priority and always renders as "Free".
  // Otherwise costMin/costMax render as a single value when equal, or a range when they
  // differ, formatted per `currency` (ISO 4217 code; omitted = USD).
  free?: boolean;
  costMin?: number;
  costMax?: number;
  currency?: string;
  // What the cost is for, which sets the label under it on the spot sheet (spotCostLabel). Parking never counts: a place
  // that is free to enter is `free` whatever its car park charges.
  //   'entry' — a ticket to get in (adult price), or, with `free`, no entry fee;
  //   'tour'  — a guided tour or a cruise, the price of the standard adult one;
  //   'ticket' — a ride or activity you pay to do where being there is free (a gondola, a bungy, a jet boat), adult price;
  //   'park'  — the spot IS a park, and the price is that park's entry fee, charged as `costPer` says;
  //   'donation' — free, with a donation asked for (with `free: true`).
  //   'open'  — free and no gate, ticket or staffed entry at all (a town, suburb, beach, lookout, open trail, lake shore), with `free: true`.
  costBasis?: 'entry' | 'tour' | 'ticket' | 'park' | 'donation' | 'open';
  // How a price is charged, when it is not a plain adult price, shown as the label in place of the type's own, title-cased:
  // "Adult/Day", "Per Vehicle/Day" for a park, "Per Night" for a track's hut or campsite fees.
  costPer?: string;
  // What a visitor must have before going: 'park-pass' — free in itself, but reached through a park pass: a park that
  // charges entry (Kakadu's pass), or a pass covering a whole system of parks (the NT Parks Visitor Pass), even when the
  // spot is itself one of those parks; `parkPass` names it, and the cost column shows that pass's price over its name.
  // 'booking' — free but entry is booked ahead; 'permit' — a permit is required (its fee, if any, is the spot's price).
  needs?: 'park-pass' | 'booking' | 'permit';
  // The pass a 'park-pass' spot needs (src/data/parkPasses.ts, where its price and name live).
  parkPass?: ParkPassId;
  // The spot's official site, when one genuinely exists (a single canonical operator/steward —
  // not a general city/tourism-board page) — whether or not the spot charges admission. Omitted
  // for spots with no single official site: open public squares/districts/streets with no one
  // steward, and attractions booked through many different third-party operators with no
  // canonical site of their own (e.g. scenic flights).
  ticketUrl?: string;
}

const DESTINATION_BY_ID = new Map(DESTINATIONS.map(d => [d.id, d]));

// ── A spot's parent, country and timezone — absent parent tolerated ───────────
// Every consumer goes through these rather than reading destinationId, so a standalone spot (no parent) works
// everywhere a parented one does.

export const isStandaloneSpot = (spot: Spot) => !spot.destinationId;
// The title a spot's photo is looked up and overridden by: its Wikipedia article (`wiki`), else its name.
export const spotPhotoTitle = (spot: Spot) => spot.wiki ?? spot.name;

/** The spot's destination, or undefined for a standalone spot (or an id no longer in DESTINATIONS). */
export function spotDestination(spot: Spot): Destination | undefined {
  return spot.destinationId ? DESTINATION_BY_ID.get(spot.destinationId) : undefined;
}
export function spotCountryCode(spot: Spot): string | undefined {
  return spot.countryCode ?? spotDestination(spot)?.countryCode;
}
export function spotCountry(spot: Spot): string | undefined {
  return spot.country ?? spotDestination(spot)?.country;
}
export function spotContinent(spot: Spot): Continent | undefined {
  return spot.continent ?? spotDestination(spot)?.continent;
}
export function spotTimezone(spot: Spot): string | undefined {
  return spot.timezone ?? spotDestination(spot)?.timezone;
}

// How wide a view frames a standalone spot (it has no destination to supply a default zoom): the span its pin
// appears at on the map, and where closing it returns the camera to.
export const STANDALONE_SPOT_SPAN_KM = 40;

// Prefix (symbol before the number) or suffix (code after it, for currencies whose symbol
// is ambiguous on its own — "kr" alone doesn't say which Nordic krona/krone).
const CURRENCY_FORMAT: Record<string, { prefix?: string; suffix?: string }> = {
  USD: { prefix: '$' },
  EUR: { prefix: '€' },
  GBP: { prefix: '£' },
  JPY: { prefix: '¥' },
  // A symbol shared by several currencies belongs to the most prominent one ($ → USD); the rest spell out their code.
  AUD: { prefix: 'AUD ' },
  NZD: { prefix: 'NZD ' },
  CHF: { prefix: 'CHF ' },
  CZK: { suffix: ' Kč' },
  SEK: { suffix: ' SEK' },
  NOK: { suffix: ' NOK' },
  DKK: { suffix: ' DKK' },
  ISK: { suffix: ' ISK' },
  PGK: { prefix: 'K' },   // the kina: Papua New Guinea quotes prices as K5
};

// One unit per range, never mixing minutes and hours, so spots read the same way and compare at a glance: a visit that
// tops out under an hour reads in minutes ("0 – 15 min", "15 – 45 min"); one that reaches an hour reads in hours for both
// ends ("0.5 – 1 hr", "1 – 1.5 hr", "2 hr"). A multi-day visit (a Great Walk, a river journey) is stored as hours (24 per
// day) and shown in days once it reaches a day: "2 – 3 days", "4 days". Up to two decimals, zeros dropped.
const numTxt = (n: number): string => String(Math.round(n * 100) / 100);
export function formatVisitTime(min: number, max: number): string {
  if (min >= 24) {
    const d = (h: number) => numTxt(h / 24);
    return max === min ? `${d(min)} ${min === 24 ? 'day' : 'days'}` : `${d(min)} – ${d(max)} days`;
  }
  if (max >= 24) return `${numTxt(min)} hr – ${numTxt(max / 24)} ${max === 24 ? 'day' : 'days'}`;
  // Under an hour reads in minutes: a quick photo stop is "0 – 15 min", not "0 – 0.25 hr".
  if (max < 1) {
    const m = (h: number) => String(Math.round(h * 60));
    return max === min ? `${m(min)} min` : `${m(min)} – ${m(max)} min`;
  }
  return max === min ? `${numTxt(min)} hr` : `${numTxt(min)} – ${numTxt(max)} hr`;
}

// Traffic-light tone for the at-a-glance icons. A range takes the tone of its LOW end, so a range that reaches a
// threshold gets the lighter tone: time is green when 1 hr is in range (min ≤ 1), yellow when 3 hr is (min ≤ 3),
// else orange; cost is green when $10 is in range (min ≤ 10), yellow when $30 is (min ≤ 30), else orange.
export type Tone = 'green' | 'yellow' | 'orange';
export const visitTimeTone = (min: number): Tone => (min <= 1 ? 'green' : min <= 3 ? 'yellow' : 'orange');
// Approximate USD per unit of each currency, only to place a price against the $10 / $30 thresholds (not for display).
const USD_PER: Record<string, number> = { USD: 1, EUR: 1.1, GBP: 1.3, JPY: 0.0067, AUD: 0.65, NZD: 0.6, CHF: 1.15, CZK: 0.044, SEK: 0.095, NOK: 0.093, DKK: 0.147, ISK: 0.0073, PGK: 0.25 };
// A free spot reached through a park pass, priced as that pass: its cost column shows the pass's price ("AUD 10") over the
// pass's name (spotCostLabel). Null for any other spot.
function passPriced(spot: Spot): Spot | null {
  if (spot.needs !== 'park-pass' || !spot.parkPass || !(spot.free || spot.costMin == null)) return null;
  const p: { costMin: number; costMax?: number; currency: string } = PARK_PASSES[spot.parkPass];
  return { ...spot, free: false, costMin: p.costMin, costMax: p.costMax ?? p.costMin, currency: p.currency, needs: undefined, parkPass: undefined };
}

export const spotCostTone = (spot: Spot): Tone => {
  const pp = passPriced(spot);
  if (pp) return spotCostTone(pp);
  if (spot.free || spot.costMin == null) return 'green';
  const usd = spot.costMin * (USD_PER[spot.currency ?? 'USD'] ?? 1);
  return usd <= 10 ? 'green' : usd <= 30 ? 'yellow' : 'orange';
};

// A price's amounts as shown: a whole number as is, one with cents always to two decimal places ("27.50", never "27.5");
// in a range, both ends take two decimals when either has cents ("27.50 – 30.00").
function costAmounts(spot: Spot): [string, string | null] {
  const min = spot.costMin!, max = spot.costMax == null || spot.costMax === min ? null : spot.costMax;
  const cents = !Number.isInteger(min) || (max != null && !Number.isInteger(max));
  const f = (n: number) => (cents ? n.toFixed(2) : String(n));
  return [f(min), max == null ? null : f(max)];
}

export function formatSpotCost(spot: Spot): string {
  const pp = passPriced(spot);
  if (pp) return formatSpotCost(pp);
  if (spot.free || spot.costMin == null) return 'Free';
  const fmt = CURRENCY_FORMAT[spot.currency ?? 'USD'] ?? CURRENCY_FORMAT.USD;
  const [lo, hi] = costAmounts(spot);
  if (hi == null) return `${fmt.prefix ?? ''}${lo}${fmt.suffix ?? ''}`;
  // One currency marker for the whole range, not one per value — "NOK 140 – 160" / "$13 –
  // 35", never "140 NOK – 160 NOK" / "$13 – $35". A suffix-style currency (the Nordic kr-
  // based codes, placed after the number on a single value to disambiguate which krona/krone
  // it is) moves to the front here instead of repeating at both ends of the range.
  if (fmt.suffix) return `${fmt.suffix.trim()} ${lo} – ${hi}`;
  return `${fmt.prefix ?? ''}${lo} – ${hi}`;
}

// The label under the cost on the spot sheet: what the price is for (see costBasis). A spot not yet classified keeps the
// old label.
export function spotCostLabel(spot: Spot): string {
  const free = spot.free || spot.costMin == null;
  if (spot.needs === 'permit') return 'Permit Needed';
  if (free && spot.needs === 'park-pass') return spot.parkPass ? PARK_PASSES[spot.parkPass].name : 'Park Pass Needed';
  if (free && spot.needs === 'booking') return 'Booking Needed';
  if (free && spot.costBasis === 'donation') return 'By Donation';
  if (free && spot.costBasis === 'open') return 'Open Access';
  if (!free && spot.costPer) return spot.costPer;
  if (!free && spot.costBasis === 'tour') return 'Tour (Adult)';
  if (!free && spot.costBasis === 'ticket') return 'Ticket (Adult)';
  if (!free && spot.costBasis === 'park') return 'Park Entry';
  if (spot.costBasis === 'entry') return free ? 'No Entry Fee' : 'Entry (Adult)';
  return 'Cost (Adult)';
}

// The same price as formatSpotCost split into its currency code and the numbers, for a column too narrow for one line
// ("AUD" over "150 – 260"). Null when there is no code to split off: free, or a symbol currency ($, €, £, ¥).
export function splitSpotCost(spot: Spot): { code: string; amount: string } | null {
  const pp = passPriced(spot);
  if (pp) return splitSpotCost(pp);
  if (spot.free || spot.costMin == null) return null;
  const fmt = CURRENCY_FORMAT[spot.currency ?? 'USD'] ?? CURRENCY_FORMAT.USD;
  const code = (fmt.suffix ?? (fmt.prefix && /^[A-Z]{3} $/.test(fmt.prefix) ? fmt.prefix : '')).trim();
  if (!code) return null;
  const [lo, hi] = costAmounts(spot);
  const amount = hi == null ? lo : `${lo} – ${hi}`;
  return { code, amount };
}

